-- paperclip:migration-safety-ignore large-create-index-not-concurrently: Drizzle migrations run transactionally, so CONCURRENTLY is unavailable. Partial index holding only runs that registered a secret: secret redaction (valuesForIssue, on every issue comments read) otherwise detoasted the full context_snapshot of every run of the issue, or of the whole table through the unindexed OR branch.
CREATE INDEX IF NOT EXISTS "heartbeat_runs_company_secret_redactions_idx" ON "heartbeat_runs" USING btree ("company_id") WHERE "heartbeat_runs"."context_snapshot" ? 'paperclipSecretRedactions';--> statement-breakpoint
-- paperclip:migration-safety-ignore large-create-index-not-concurrently: Drizzle migrations run transactionally, so CONCURRENTLY is unavailable. Indexes the second branch of the valuesForIssue OR (context_snapshot -> 'paperclipIssue' ->> 'id'), which forced a sequential scan of heartbeat_runs.
CREATE INDEX IF NOT EXISTS "heartbeat_runs_company_ctx_paperclip_issue_idx" ON "heartbeat_runs" USING btree ("company_id",(("context_snapshot" -> 'paperclipIssue') ->> 'id'));--> statement-breakpoint
-- paperclip:migration-safety-ignore large-create-index-not-concurrently: Drizzle migrations run transactionally, so CONCURRENTLY is unavailable. Partial indexes stay small (only issues holding a run lock); withIssueExecutionLock otherwise scanned issues four times per run release.
CREATE INDEX IF NOT EXISTS "issues_execution_run_idx" ON "issues" USING btree ("execution_run_id") WHERE "issues"."execution_run_id" is not null;--> statement-breakpoint
-- paperclip:migration-safety-ignore large-create-index-not-concurrently: Drizzle migrations run transactionally, so CONCURRENTLY is unavailable. See issues_execution_run_idx.
CREATE INDEX IF NOT EXISTS "issues_checkout_run_idx" ON "issues" USING btree ("checkout_run_id") WHERE "issues"."checkout_run_id" is not null;
